'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\r\n\r\n\r\n', [[''], [''], ['']]],
  ['\r\r\n\n', [[''], [''], ['']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  [',,', [['', '', '']]],
  ['a,,b,', [['a', '', 'b', '']]],
  ['""', [['']]],
  ['""""', [['"']]],
  ['"a,b","say ""hi"""\n', [['a,b', 'say "hi"']]],
  ['"a\r\nb\rc\nd",tail\r\nnext', [['a\r\nb\rc\nd', 'tail'], ['next']]],
  ['ab"cd,ef"\n', [['ab"cd', 'ef"']]],
  ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';', header: true }],
  ['a\t"b\tc"\t', [['a', 'b\tc', '']], { delimiter: '\t' }],
  ['a\uD800b', [['a', 'b']], { delimiter: '\uD800' }],
  ['x😀y,"😀"', [['x😀y', '😀']]],
];

test('valid records are invariant across every pair of chunk boundaries', () => {
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, { ...options, header: false }), expected);
    for (let first = 0; first <= text.length; first++) {
      for (let second = first; second <= text.length; second++) {
        const parser = createParser(options);
        const records = [];
        for (const chunk of [text.slice(0, first), '', text.slice(first, second), '', text.slice(second)]) {
          records.push(...parser.push(chunk));
        }
        records.push(...parser.end());
        assert.deepEqual(records, expected, JSON.stringify({ text, first, second }));
        assert.deepEqual(parser.end(), []);
        assert.throws(() => parser.push(''), Error);
      }
    }
    const parser = createParser(options);
    const records = [];
    for (let index = 0; index < text.length; index++) {
      records.push(...parser.push(''), ...parser.push(text[index]));
    }
    records.push(...parser.end());
    assert.deepEqual(records, expected);
  }
});

test('push emits at CR immediately and never repeats completed records', () => {
  const parser = createParser();
